// Canonical product store (Fundamentals #6 / observability-canonical-store.md),
// server impure half: local HTTP server over Unix domain socket (Bun.serve).
//
// Invariant: The server is the exclusive runtime owner of SQLite.

import type { Database } from "bun:sqlite";
import { unlinkSync } from "node:fs";
import type { HopTrail } from "#review/findings";
import type { CanonicalFindingRow, CanonicalRunRow } from "#store/preflight";
import {
  exportFindingsDocument,
  getFindingTriageByRunId,
  getRunById,
  openProductStore,
  recordFindingTriage,
  saveRunTransaction,
} from "#store/store";
import {
  type FindingDetail,
  type HealthResponse,
  type ListRunsResponse,
  matchRoute,
  parseListRunsQuery,
  parseSearchFindingsQuery,
  parseUsageQuery,
  type RecordTriageRequestBody,
  type RecordTriageResponse,
  type SaveRunRequestBody,
  type SaveRunResponse,
  type SearchFindingsResponse,
  type UsageResponse,
} from "./preflight";

// The store keeps `cost_usd_est` as a legacy column (0 on every run since the platform prices runs,
// odd/tasks/platform-owned-cost.md S3): no dollar leaves the engine through this API, where a 0
// would read as a free run.
function withoutLegacyCost(row: CanonicalRunRow): CanonicalRunRow {
  const { cost_usd_est: _legacy, ...rest } = row as CanonicalRunRow & {
    cost_usd_est?: unknown;
  };
  return rest;
}

export interface ServerOptions {
  dbPath: string;
  socketPath?: string;
  port?: number;
  hostname?: string;
}

export interface StoreServerHandle {
  db: Database;
  url: string;
  socketPath?: string;
  stop: () => void;
}

export function startProductStoreServer(
  options: ServerOptions,
): StoreServerHandle {
  const db = openProductStore(options.dbPath);

  if (options.socketPath) {
    try {
      unlinkSync(options.socketPath);
    } catch {}
  }

  async function fetchHandler(req: Request): Promise<Response> {
    try {
      const url = new URL(req.url);
      const match = matchRoute(req.method, url.pathname);

      if (!match) {
        return Response.json({ error: "Not found" }, { status: 404 });
      }

      switch (match.name) {
        case "health": {
          const count = (
            db.query("SELECT COUNT(*) as c FROM runs;").get() as { c: number }
          ).c;
          const version = (
            db.query("PRAGMA user_version;").get() as { user_version: number }
          ).user_version;
          const body: HealthResponse = {
            status: "ok",
            schema_version: version,
            runs_count: count,
          };
          return Response.json(body);
        }

        case "save_run": {
          const body = (await req.json()) as SaveRunRequestBody;
          if (!body?.projected?.run) {
            return Response.json(
              { error: "Invalid payload: projected run required" },
              { status: 400 },
            );
          }
          const runId = saveRunTransaction(db, body.projected);
          const response: SaveRunResponse = {
            ok: true,
            run_id: runId,
            run_dir: body.projected.run.run_dir,
          };
          return Response.json(response);
        }

        case "list_runs": {
          const query = parseListRunsQuery(url);
          let sql = "SELECT * FROM runs WHERE 1=1";
          const params: (string | number)[] = [];

          if (query.repo_id) {
            sql += " AND repo_id = ?";
            params.push(query.repo_id);
          }
          if (query.pr !== undefined) {
            if (query.pr === 0) {
              sql += " AND (pr = 0 OR pr IS NULL)";
            } else {
              sql += " AND pr = ?";
              params.push(query.pr);
            }
          }
          sql += " ORDER BY generated_at DESC";
          if (query.limit !== undefined) {
            sql += " LIMIT ?";
            params.push(query.limit);
          }

          const runs = (db.query(sql).all(...params) as CanonicalRunRow[]).map(
            withoutLegacyCost,
          );
          const response: ListRunsResponse = { runs };
          return Response.json(response);
        }

        case "get_run": {
          const id = Number(match.params.id);
          const run = getRunById(db, id);
          if (!run) {
            return Response.json({ error: "Run not found" }, { status: 404 });
          }
          return Response.json({ run: withoutLegacyCost(run) });
        }

        case "get_run_findings_doc": {
          const id = Number(match.params.id);
          const doc = exportFindingsDocument(db, id);
          if (!doc) {
            return Response.json(
              { error: "Run not found or invalid" },
              { status: 404 },
            );
          }
          return Response.json(doc);
        }

        case "get_run_triage": {
          const id = Number(match.params.id);
          const triage = getFindingTriageByRunId(db, id);
          return Response.json({ triage });
        }

        case "record_run_triage": {
          const id = Number(match.params.id);
          const run = getRunById(db, id);
          if (!run) {
            return Response.json({ error: "Run not found" }, { status: 404 });
          }
          const body = (await req.json()) as RecordTriageRequestBody;
          const triageId = recordFindingTriage(db, {
            run_id: id,
            finding_id: body.finding_id,
            comment_id: body.comment_id ?? null,
            tag: body.tag,
            verdict: body.verdict ?? null,
            actor: body.actor,
            reasoning: body.reasoning,
            issue_number: body.issue_number ?? null,
            created_at: body.created_at ?? new Date().toISOString(),
          });
          const response: RecordTriageResponse = { ok: true, id: triageId };
          return Response.json(response);
        }

        case "get_usage": {
          const query = parseUsageQuery(url);
          let sql = "SELECT * FROM runs";
          const params: string[] = [];

          if (!query.all && query.repo_id) {
            sql += " WHERE repo_id = ?";
            params.push(query.repo_id);
          }
          sql += " ORDER BY generated_at DESC;";

          const rows = (db.query(sql).all(...params) as CanonicalRunRow[]).map(
            withoutLegacyCost,
          );
          let total_tokens = 0;

          for (const r of rows) {
            total_tokens += r.tokens_total;
          }

          const response: UsageResponse = {
            rows,
            total_tokens,
          };
          return Response.json(response);
        }

        case "search_findings": {
          const query = parseSearchFindingsQuery(url);
          let sql = `
              SELECT f.*, r.run_dir, r.repo_id
              FROM findings f
              JOIN runs r ON f.run_id = r.id
              WHERE 1=1
            `;
          const params: (string | number)[] = [];

          if (query.repo_id) {
            sql += " AND r.repo_id = ?";
            params.push(query.repo_id);
          }
          if (query.run_id !== undefined) {
            sql += " AND f.run_id = ?";
            params.push(query.run_id);
          }
          if (query.tier) {
            sql += " AND f.tier = ?";
            params.push(query.tier);
          }
          if (query.path) {
            sql += " AND f.path = ?";
            params.push(query.path);
          }
          sql += " ORDER BY f.run_id DESC, f.finding_order ASC";
          if (query.limit !== undefined) {
            sql += " LIMIT ?";
            params.push(query.limit);
          }

          const rows = db.query(sql).all(...params) as (CanonicalFindingRow & {
            id: number;
            run_dir: string;
            repo_id: string;
          })[];

          const findings: FindingDetail[] = [];
          for (const row of rows) {
            const proofRefRows = db
              .query(
                "SELECT proof_ref FROM finding_proof_refs WHERE finding_id = ? ORDER BY ref_order ASC",
              )
              .all(row.id) as { proof_ref: string }[];

            const hopTrailRows = db
              .query(
                "SELECT step_num, kind, query, reached, is_raw_string FROM finding_hop_trail WHERE finding_id = ? ORDER BY step_order ASC",
              )
              .all(row.id) as {
              step_num: number;
              kind: string;
              query: string;
              reached: string | null;
              is_raw_string: number;
            }[];

            const isRaw =
              hopTrailRows.length > 0 && hopTrailRows[0]?.is_raw_string === 1;
            const hop_trail: HopTrail = isRaw
              ? hopTrailRows.map((h) => h.query)
              : hopTrailRows.map((h) => ({
                  step: h.step_num,
                  kind: h.kind,
                  query: h.query,
                  reached: h.reached ?? "",
                }));

            findings.push({
              ...row,
              proof_refs: proofRefRows.map((p) => p.proof_ref),
              hop_trail,
            });
          }

          const response: SearchFindingsResponse = { findings };
          return Response.json(response);
        }
      }
    } catch (error) {
      return Response.json(
        { error: (error as Error).message },
        { status: 500 },
      );
    }
  }

  let server: ReturnType<typeof Bun.serve>;
  try {
    server = options.socketPath
      ? Bun.serve({
          unix: options.socketPath,
          fetch: fetchHandler,
        })
      : Bun.serve({
          ...(options.port !== undefined ? { port: options.port } : {}),
          ...(options.hostname !== undefined
            ? { hostname: options.hostname }
            : {}),
          fetch: fetchHandler,
        });
  } catch (err) {
    db.close();
    throw err;
  }

  return {
    db,
    url: server.url?.toString() ?? `unix:${options.socketPath}`,
    socketPath: options.socketPath,
    stop: () => {
      server.stop(true);
      db.close();
      if (options.socketPath) {
        try {
          unlinkSync(options.socketPath);
        } catch {}
      }
    },
  };
}

// The npm entry point (bin/pr-hero.js) runs under Node (npx) and under Bun
// (bun install -g, a checkout). These tests pin the Node path: Bun discovery
// order, argument forwarding, exit-code and signal propagation, and the
// message when no Bun exists. Fixtures copy the REAL launcher into a temp
// package so nothing here depends on the repo's own node_modules.
import { afterEach, beforeEach, expect, test } from "bun:test";
import {
  chmodSync,
  copyFileSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  realpathSync,
  rmSync,
  symlinkSync,
  writeFileSync,
} from "node:fs";
import os from "node:os";
import path from "node:path";

const REPO = path.resolve(import.meta.dir, "..", "..");
const REAL_LAUNCHER = path.join(REPO, "bin", "pr-hero.js");
const NODE = Bun.which("node") ?? "node";
const NOT_FOUND_MESSAGE =
  "crysk: Bun was not found. Crysk runs on Bun (>= 1.3): install it from https://bun.sh, or install Crysk with npm i -g crysk.\n";

let tmp = "";
let pkg = "";

beforeEach(() => {
  tmp = mkdtempSync(path.join(realpathSync(os.tmpdir()), "prhero-launcher-"));
  pkg = path.join(tmp, "pkg");
  mkdirSync(path.join(pkg, "bin"), { recursive: true });
  copyFileSync(REAL_LAUNCHER, path.join(pkg, "bin", "pr-hero.js"));
  writeFileSync(
    path.join(pkg, "package.json"),
    JSON.stringify({ type: "module" }),
  );
});

afterEach(() => {
  rmSync(tmp, { recursive: true, force: true });
});

function launcher(): string {
  return path.join(pkg, "bin", "pr-hero.js");
}

function writeExecutable(file: string, body: string): void {
  mkdirSync(path.dirname(file), { recursive: true });
  writeFileSync(file, `#!/bin/sh\n${body}\n`);
  chmodSync(file, 0o755);
}

// The launcher probes a Bun with `--version` before using it, so every fake that
// must reach its real behavior answers that probe first.
const VERSION_OK = `if [ "$1" = "--version" ]; then echo 1.3.14; exit 0; fi`;

function fakeBunOn(dir: string, body: string): string {
  const file = path.join(dir, "bun");
  writeExecutable(file, body);
  return file;
}

// Directory holding a `node` link, but no `bun`. Node's own dir may contain
// bun (e.g. a version manager), so the link is made in a separate directory.
function nodeOnlyDir(): string {
  const dir = path.join(tmp, "node-only");
  mkdirSync(dir, { recursive: true });
  symlinkSync(NODE, path.join(dir, "node"));
  return dir;
}

function runLauncher(args: string[], env: Record<string, string>) {
  return Bun.spawnSync([NODE, launcher(), ...args], {
    env,
    stdout: "pipe",
    stderr: "pipe",
  });
}

const decode = (bytes: Uint8Array): string => new TextDecoder().decode(bytes);

